class Solution {
public:
    int countCollisions(string directions) {
        int ans = 0;
        int r_count = 0;
        bool has_s = false;
        for (char d : directions) {
            if (d == 'R') {
                r_count++;
            } else if (d == 'S') {
                ans += r_count;
                r_count = 0;
                has_s = true;
            } else {
                if (r_count > 0) {
                    ans += r_count + 1;
                    r_count = 0;
                    has_s = true;
                } else if (has_s) {
                    ans += 1;
                }
            }
        }
        return ans;
    }
};
